declare(strict_types=1);require_once __DIR__.'/../config/koneksi.php';require_once __DIR__.'/../vendor/autoload.php';use EnglAI\Learning\{AssessmentService,Level,ProgressService,WritingSessionService};use EnglAI\Mvp\StudentSession;use EnglAI\Security\Csrf;
$pdo=db();$m=StudentSession::requireMember($pdo);$mid=(int)$m['id'];$cid=(int)$m['classroom_id'];$svc=new WritingSessionService($pdo);function wjson(array $d,int $s=200):never{http_response_code($s);header('Content-Type: application/json; charset=UTF-8');echo json_encode($d,JSON_UNESCAPED_UNICODE);exit;}
if($_SERVER['REQUEST_METHOD']==='POST'){try{Csrf::requireValid($_POST['csrf_token']??null);$sid=(int)($_POST['session_id']??0);$task=(int)($_POST['task_id']??0);$action=(string)($_POST['action']??'submit');$session=$svc->get($sid,$mid,$cid);$tasks=json_decode((string)$session['task_snapshot_json'],true)?:[];$current=$tasks[(int)$session['current_position']]??null;if($session['status']!=='active'||!$current||(int)$current['id']!==$task)throw new RuntimeException('Task tidak sesuai session.');if($action==='ready'){$pdo->prepare('UPDATE writing_sessions SET task_started_at=COALESCE(task_started_at,NOW()),task_deadline_at=COALESCE(task_deadline_at,DATE_ADD(NOW(),INTERVAL 30 SECOND)) WHERE id=?')->execute([$sid]);wjson(['success'=>true,'state'=>$svc->state($svc->get($sid,$mid,$cid))]);}$answer=trim((string)($_POST['answer']??''));$timed=($_POST['timed_out']??'0')==='1';$key=(string)($_POST['idempotency_key']??'');if(!preg_match('/^[a-f0-9]{64}$/',$key)||mb_strlen($answer)>(int)$current['max_chars'])throw new RuntimeException('Submission tidak valid.');$q=$pdo->prepare('SELECT id FROM writing_submissions WHERE session_id=? AND task_id=?');$q->execute([$sid,$task]);if($q->fetchColumn())wjson(['success'=>true,'idempotent'=>true,'state'=>$svc->state($svc->get($sid,$mid,$cid))]);$clock=$pdo->prepare('SELECT task_started_at,task_deadline_at,TIMESTAMPDIFF(MICROSECOND,task_started_at,LEAST(NOW(),task_deadline_at))/1000 response_ms,NOW()>task_deadline_at expired FROM writing_sessions WHERE id=?');$clock->execute([$sid]);$time=$clock->fetch();if(!$timed&&(bool)$time['expired'])throw new RuntimeException('Deadline telah berakhir.');$status=$answer===''?'no_response':($timed?'timed_out':'submitted');$assessment=null;$score=null;$assessmentStatus=$answer===''?'no_response':'needs_review';if($answer!==''){$a=$pdo->prepare('SELECT * FROM learning_activities WHERE id=? AND classroom_id=?');$a->execute([$task,$cid]);if($activity=$a->fetch()){try{$assessment=(new AssessmentService($pdo))->assess('writing',$answer,$activity);$score=(float)$assessment['total_score'];$assessmentStatus=$assessment['status']==='completed'?'assessed':'needs_review';}catch(Throwable){$assessmentStatus='failed';}}}$pdo->beginTransaction();try{$pdo->prepare('INSERT INTO writing_submissions(session_id,task_id,member_id,classroom_id,idempotency_key,answer_text,submission_status,response_time_ms,assessment_json,assessment_status,score,submitted_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,NOW())')->execute([$sid,$task,$mid,$cid,$key,$answer!==''?$answer:null,$status,max(0,min(30000,(int)$time['response_ms'])),$assessment?json_encode($assessment,JSON_UNESCAPED_UNICODE):null,$assessmentStatus,$score]);$next=(int)$session['current_position']+1;$done=$next>=10;$pdo->prepare('UPDATE writing_sessions SET current_position=?,status=?,completed_at=?,task_started_at=NULL,task_deadline_at=NULL WHERE id=? AND current_position=?')->execute([$next,$done?'completed':'active',$done?date('Y-m-d H:i:s'):null,$sid,(int)$session['current_position']]);$pdo->commit();if($done)(new ProgressService($pdo))->refresh($cid,$mid,'writing',$session['level'],$task);}catch(Throwable $e){$pdo->rollBack();throw $e;}wjson(['success'=>true,'message'=>'Jawaban tersimpan.','state'=>$svc->state($svc->get($sid,$mid,$cid))]);}catch(Throwable $e){wjson(['success'=>false,'message'=>$e->getMessage()],422);}}
$level=Level::validate((string)($_GET['level']??'intermediate'));try{$session=isset($_GET['session'])?$svc->get((int)$_GET['session'],$mid,$cid):$svc->start($mid,$cid,$level,isset($_GET['play_again']));$state=$svc->state($session);}catch(Throwable $e){header('Location: /student/skill.php?skill=writing&message='.rawurlencode($e->getMessage()));exit;}
